BEGIN;
CREATE TABLE IF NOT EXISTS app_settings (key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS users (id bigserial PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'viewer' CHECK(role IN ('admin','manager','accountant','viewer')), active boolean NOT NULL DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS shops (id bigserial PRIMARY KEY, number text NOT NULL UNIQUE, floor text NOT NULL DEFAULT '', rent numeric(18,2) NOT NULL CHECK(rent>=0), status text NOT NULL DEFAULT 'vacant' CHECK(status IN('vacant','occupied','maintenance')), notes text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tenants (id bigserial PRIMARY KEY, name text NOT NULL, phone text NOT NULL DEFAULT '', identity_no text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (id bigserial PRIMARY KEY, name text NOT NULL UNIQUE, type text NOT NULL CHECK(type IN('cash','bank')), opening_balance numeric(18,2) NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS contracts (id bigserial PRIMARY KEY, shop_id bigint NOT NULL REFERENCES shops(id), tenant_id bigint NOT NULL REFERENCES tenants(id), start_date date NOT NULL, end_date date NOT NULL, monthly_rent numeric(18,2) NOT NULL CHECK(monthly_rent>=0), deposit numeric(18,2) NOT NULL DEFAULT 0 CHECK(deposit>=0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','closed')), notes text NOT NULL DEFAULT '', created_at timestamptz DEFAULT now(), CHECK(end_date>=start_date));
CREATE UNIQUE INDEX IF NOT EXISTS ux_active_shop_contract ON contracts(shop_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS rent_charges (id bigserial PRIMARY KEY, contract_id bigint NOT NULL REFERENCES contracts(id), period date NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount>=0), UNIQUE(contract_id,period));
CREATE TABLE IF NOT EXISTS receipts (id bigserial PRIMARY KEY, tenant_id bigint NOT NULL REFERENCES tenants(id), account_id bigint NOT NULL REFERENCES accounts(id), amount numeric(18,2) NOT NULL CHECK(amount>0), receipt_date date NOT NULL DEFAULT CURRENT_DATE, reference text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_by bigint REFERENCES users(id), created_at timestamptz DEFAULT now(), voided_at timestamptz, void_reason text);
CREATE TABLE IF NOT EXISTS receipt_allocations (receipt_id bigint NOT NULL REFERENCES receipts(id), charge_id bigint NOT NULL REFERENCES rent_charges(id), amount numeric(18,2) NOT NULL CHECK(amount>0), PRIMARY KEY(receipt_id,charge_id));
CREATE TABLE IF NOT EXISTS expenses (id bigserial PRIMARY KEY, category text NOT NULL, description text NOT NULL DEFAULT '', amount numeric(18,2) NOT NULL CHECK(amount>0), account_id bigint NOT NULL REFERENCES accounts(id), entry_date date NOT NULL DEFAULT CURRENT_DATE, created_by bigint REFERENCES users(id), created_at timestamptz DEFAULT now(), voided_at timestamptz, void_reason text);
CREATE TABLE IF NOT EXISTS partners (id bigserial PRIMARY KEY, name text NOT NULL, phone text NOT NULL DEFAULT '', share numeric(7,4) NOT NULL CHECK(share>=0 AND share<=100), capital numeric(18,2) NOT NULL DEFAULT 0 CHECK(capital>=0), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS distributions (id bigserial PRIMARY KEY, period date NOT NULL UNIQUE, amount numeric(18,2) NOT NULL CHECK(amount>=0), notes text NOT NULL DEFAULT '', created_by bigint REFERENCES users(id), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS partner_distributions (distribution_id bigint NOT NULL REFERENCES distributions(id), partner_id bigint NOT NULL REFERENCES partners(id), share_snapshot numeric(7,4) NOT NULL, amount numeric(18,2) NOT NULL, PRIMARY KEY(distribution_id,partner_id));
CREATE TABLE IF NOT EXISTS withdrawals (id bigserial PRIMARY KEY, partner_id bigint NOT NULL REFERENCES partners(id), account_id bigint NOT NULL REFERENCES accounts(id), amount numeric(18,2) NOT NULL CHECK(amount>0), kind text NOT NULL CHECK(kind IN('profit','capital','advance','loan')), entry_date date NOT NULL DEFAULT CURRENT_DATE, notes text NOT NULL DEFAULT '', approved_by bigint NOT NULL REFERENCES users(id), created_at timestamptz DEFAULT now(), voided_at timestamptz, void_reason text);
CREATE TABLE IF NOT EXISTS transfers (id bigserial PRIMARY KEY, from_account bigint NOT NULL REFERENCES accounts(id), to_account bigint NOT NULL REFERENCES accounts(id), amount numeric(18,2) NOT NULL CHECK(amount>0), entry_date date NOT NULL DEFAULT CURRENT_DATE, notes text NOT NULL DEFAULT '', created_by bigint REFERENCES users(id), created_at timestamptz DEFAULT now(), CHECK(from_account<>to_account));
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, user_id bigint REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id bigint, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
INSERT INTO accounts(name,type,opening_balance) VALUES('Cashbox','cash',0) ON CONFLICT(name) DO NOTHING;
INSERT INTO app_settings(key,value) VALUES('market', '{"name":"My Market","currency":"AFN"}') ON CONFLICT(key) DO NOTHING;
COMMIT;
